function flash(string $m): void { $_SESSION['flash'] = $m; }
function qs(array $change = []): string { $q = array_merge($_GET, $change); foreach ($q as $k => $v) if ($v === '' || $v === null) unset($q[$k]); return $q ? '?' . http_build_query($q) : ''; }
function opt(array $values, string $current, bool $assoc = false): string {
    $o = '';
    foreach ($values as $k => $v) { $val = $assoc ? (string)$k : (string)$v; $o .= '<option value="' . h($val) . '"' . ($val === $current ? ' selected' : '') . '>' . h($v) . '</option>'; }
    return $o;
}
const SECTIONS = ['Booster Boxes', 'Booster Box Cases', 'Booster Packs', 'Elite Trainer Boxes', 'Premium & Special Sets', 'Single Cards', 'PSA Graded Cards', 'Accessories',
                  'Booster & Hobby Boxes', 'Cases', 'Packs', 'Decks, Bundles & Sets', 'Graded Cards', 'Collectibles'];
const POKE_SECTION_URL = ['Booster Boxes' => '/booster-boxes', 'Booster Box Cases' => '/booster-box-cases', 'Booster Packs' => '/booster-packs', 'Elite Trainer Boxes' => '/elite-trainer-boxes',
                          'Premium & Special Sets' => '/premium-special-sets', 'Single Cards' => '/single-cards', 'PSA Graded Cards' => '/cards/psa-graded-pokemon-cards', 'Accessories' => '/accessories'];
function section_url_for(string $game, string $section): string {
    if ($game === 'PokÃ©mon' || $game === 'Accessories') return POKE_SECTION_URL[$section] ?? (POKE_SECTION_URL[str_replace(['Graded Cards', 'Packs', 'Cases'], ['PSA Graded Cards', 'Booster Packs', 'Booster Box Cases'], $section)] ?? '/shop');
    $g = one("SELECT path FROM collections WHERE kind = 'game' AND game = ?", [$game]);
    $base = $g ? $g['path'] : '/' . slugify($game);
    $sec = $section === 'PSA Graded Cards' ? 'Graded Cards' : ($section === 'Booster Packs' ? 'Packs' : $section);
    $url = $base . '/' . slugify($sec);
    if (!one('SELECT 1 FROM collections WHERE path = ?', [$url])) q("INSERT INTO collections(path, kind, title, h1, game) VALUES(?, 'game_section', ?, ?, ?)", [$url, "$game: $sec", "$game " . mb_strtolower($sec), $game]);
    if (!$g) q("INSERT OR IGNORE INTO collections(path, kind, title, h1, game) VALUES(?, 'game', ?, ?, ?)", [$base, "$game cards", "$game cards", $game]);
    return $url;
}
function games(): array { return array_column(all('SELECT DISTINCT game FROM products ORDER BY game = \'PokÃ©mon\' DESC, game'), 'game'); }

