function admin_pager(int $page, int $pages): string {
    if ($pages <= 1) return '';
    $o = '<nav class="pager">';
    if ($page > 1) $o .= '<a href="' . h(qs(['page' => $page - 1])) . '">â† Previous</a>';
    $o .= "<span>Page $page of $pages</span>";
    if ($page < $pages) $o .= '<a href="' . h(qs(['page' => $page + 1])) . '">Next â†’</a>';
    return $o . '</nav>';
}
function admin_products_bulk(): void {
    $ids = array_map('intval', $_POST['ids'] ?? []);
    $back = (string)($_POST['back'] ?? '/admin/products');
    if (!str_starts_with($back, '/admin')) $back = '/admin/products';
    if (!$ids || empty($_POST['action'])) { flash('Select some products and an action first.'); redirect($back); }
    $in = implode(',', $ids);
    $map = ['stock1' => 'in_stock = 1', 'stock0' => 'in_stock = 0', 'pub1' => 'published = 1', 'pub0' => 'published = 0', 'seo1' => 'seo_index = 1', 'seo0' => 'seo_index = 0', 'feat1' => 'featured = 1', 'feat0' => 'featured = 0'];
    $a = $_POST['action'];
    if (isset($map[$a])) q("UPDATE products SET {$map[$a]}, updated_at = datetime('now') WHERE id IN ($in)");
    elseif ($a === 'price' && is_numeric($_POST['pct'] ?? null)) {
        $f = 1 + (float)$_POST['pct'] / 100;
        q("UPDATE products SET price_usd = ROUND(price_usd * ?, 2), updated_at = datetime('now') WHERE id IN ($in) AND price_usd IS NOT NULL", [$f]);
        foreach (all("SELECT id, breaks FROM products WHERE id IN ($in) AND breaks IS NOT NULL") as $r) {
            $b = array_map(fn($x) => [(int)$x[0], round((float)$x[1] * $f, 2)], json_decode($r['breaks'], true) ?: []);
            q('UPDATE products SET breaks = ? WHERE id = ?', [json_encode($b), $r['id']]);
        }
    } elseif ($a === 'delete') { q("DELETE FROM products WHERE id IN ($in)"); q("DELETE FROM product_paths WHERE product_id IN ($in)"); }
    flash('Updated ' . count($ids) . ' product' . (count($ids) === 1 ? '' : 's') . '.');
    redirect($back);
}
function parse_breaks(string $s): ?string {
    $out = [];
    foreach (preg_split('/[,\n]+/', $s) as $part) if (preg_match('/^\s*(\d+)\s*[:=@]\s*\$?([\d.]+)\s*$/', $part, $m)) $out[] = [(int)$m[1], (float)$m[2]];
    if (!$out) return null;
    usort($out, fn($a, $b) => $a[0] <=> $b[0]);
    return json_encode($out);
}
function admin_product_edit(): void {
    $id = (int)($_GET['id'] ?? 0);
    $p = $id ? one('SELECT * FROM products WHERE id = ?', [$id]) : null;
    if ($id && !$p) { flash('That product no longer exists.'); redirect('/admin/products'); }
    $p = $p ?: ['id' => 0, 'title' => '', 'handle' => '', 'game' => 'PokÃ©mon', 'section' => 'Booster Boxes', 'subsection' => '', 'set_name' => '', 'set_url' => '', 'series' => '', 'language' => 'Japanese',
        'card_name' => '', 'card_number' => '', 'rarity' => '', 'card_type' => '', 'variant' => '', 'sku' => '', 'price_usd' => null, 'compare_usd' => null, 'moq' => null, 'step' => null, 'breaks' => null,
        'in_stock' => 1, 'published' => 1, 'seo_index' => 1, 'featured' => 0, 'also_on' => '', 'image_url' => '', 'image_local' => '', 'alt_text' => '', 'description' => '', 'seo_title' => '', 'meta_desc' => '', 'section_url' => '', 'game_url' => '', 'weight_kg' => null, 'desc_auto' => 1];
    $err = '';
    if (is_post()) {
        $d = $_POST;
        $title = trim((string)$d['title']);
        $handle = slugify(trim((string)($d['handle'] ?? '')) ?: $title);
        if ($title === '') $err = 'Give the product a title.';
        elseif (one('SELECT 1 FROM products WHERE handle = ? AND id != ?', [$handle, $id])) $err = 'Another product already uses that web address. Change the "Web address" field.';
        if (!$err) {
            $game = trim((string)$d['game']) ?: 'PokÃ©mon';
            $section = in_array($d['section'], SECTIONS, true) ? $d['section'] : 'Single Cards';
            $setUrl = trim((string)$d['set_url']);
            if ($setUrl === '' && trim((string)$d['set_name']) !== '') {
                $setUrl = ($game === 'PokÃ©mon' ? '' : '/' . slugify($game)) . '/sets/' . slugify((string)$d['set_name']);
                q("INSERT OR IGNORE INTO collections(path, kind, title, h1, game, series) VALUES(?, 'set', ?, ?, ?, ?)", [$setUrl, $d['set_name'], $d['set_name'] . ($game === 'PokÃ©mon' ? ' PokÃ©mon cards' : " $game cards"), $game, $d['series'] ?? '']);
            }
            $img = trim((string)$d['image_url']);
            $vals = ['title' => $title, 'handle' => $handle, 'game' => $game, 'section' => $section, 'subsection' => trim((string)$d['subsection']), 'section_url' => section_url_for($game, $section),
                'game_url' => $game === 'PokÃ©mon' ? '/pokemon' : ($game === 'Accessories' ? '' : (one("SELECT path FROM collections WHERE kind='game' AND game=?", [$game])['path'] ?? '')),
                'set_name' => trim((string)$d['set_name']), 'set_url' => $setUrl, 'series' => trim((string)$d['series']), 'language' => $d['language'], 'card_name' => trim((string)$d['card_name']),
                'card_number' => trim((string)$d['card_number']), 'rarity' => trim((string)$d['rarity']), 'card_type' => trim((string)$d['card_type']), 'variant' => trim((string)$d['variant']), 'sku' => trim((string)$d['sku']),
                'price_usd' => is_numeric($d['price_usd']) ? round((float)$d['price_usd'], 2) : null, 'compare_usd' => is_numeric($d['compare_usd']) ? round((float)$d['compare_usd'], 2) : null,
                'moq' => is_numeric($d['moq']) ? max(1, (int)$d['moq']) : null, 'step' => is_numeric($d['step']) ? max(1, (int)$d['step']) : null, 'breaks' => parse_breaks((string)$d['breaks']),
                'in_stock' => isset($d['in_stock']) ? 1 : 0, 'published' => isset($d['published']) ? 1 : 0, 'seo_index' => isset($d['seo_index']) ? 1 : 0, 'featured' => isset($d['featured']) ? 1 : 0,
                'also_on' => trim(preg_replace('/\s+/', ' ', (string)$d['also_on'])), 'image_url' => $img, 'alt_text' => trim((string)$d['alt_text']), 'description' => sanitize_html((string)$d['description']),
                'seo_title' => trim((string)$d['seo_title']), 'meta_desc' => trim((string)$d['meta_desc']), 'weight_kg' => is_numeric($d['weight_kg'] ?? null) && (float)$d['weight_kg'] > 0 ? round((float)$d['weight_kg'], 3) : null,
                'sort_number' => preg_match('/[A-Za-z]*0*(\d+)/', (string)$d['card_number'], $m) ? (float)$m[1] : null];
            if ($img !== $p['image_url']) $vals['image_local'] = '';
            // a description edited by hand is kept; an untouched automatic one stays automatic (and is rewritten if card details change)
            $norm = fn($x) => trim(preg_replace('/\s+/u', ' ', html_entity_decode(strip_tags((string)$x), ENT_QUOTES)));
            $vals['desc_auto'] = $norm($vals['description']) === '' ? 1 : (($id && $norm($vals['description']) !== $norm($p['description'] ?? '')) ? 0 : (int)($p['desc_auto'] ?? 1));
            if (!empty($d['image_local_new'])) { $vals['image_local'] = ltrim((string)$d['image_local_new'], '/'); }
            if ($id) {
                q('UPDATE products SET ' . implode(', ', array_map(fn($k) => "$k = ?", array_keys($vals))) . ", updated_at = datetime('now') WHERE id = ?", [...array_values($vals), $id]);
            } else {
                q('INSERT INTO products(' . implode(',', array_keys($vals)) . ", source) VALUES(" . implode(',', array_fill(0, count($vals), '?')) . ", 'manual')", array_values($vals));
                $id = (int)db()->lastInsertId();
            }
            sync_product_paths($id);
            $saved = one('SELECT * FROM products WHERE id = ?', [$id]);
            if ($saved && (int)$saved['desc_auto'] === 1) q('UPDATE products SET description = ? WHERE id = ?', [describe_product($saved), $id]);
            flash('Saved.');
            redirect('/admin/products/edit?id=' . $id);
        }
        $p = array_merge($p, $_POST);
    }
    $sets = all("SELECT path, title, game FROM collections WHERE kind = 'set' ORDER BY game != 'PokÃ©mon', game, title");
    $lad = ladder(array_merge($p, ['price_usd' => is_numeric($p['price_usd']) ? (float)$p['price_usd'] : null]));
    $breakText = $p['breaks'] ? implode(', ', array_map(fn($b) => $b[0] . ':' . $b[1], json_decode((string)$p['breaks'], true) ?: [])) : '';
    $img = product_image($p);
    ob_start(); ?>
