/* ------------------------------------------------------------------ tools */
function admin_tools(): void {
    if (is_post() && ($_POST['do'] ?? '') === 'rebuild') { $n = rebuild_all_paths(); flash("Re-linked $n products to their pages."); redirect('/admin/tools'); }
    if (is_post() && ($_POST['do'] ?? '') === 'describe') { @set_time_limit(300); $n = describe_fill(false); flash("Rewrote $n automatic descriptions. Descriptions you edited by hand were not touched."); redirect('/admin/tools'); }
    $remote = (int)val("SELECT COUNT(*) FROM products WHERE image_local = '' AND image_url != ''");
    $local = (int)val("SELECT COUNT(*) FROM products WHERE image_local NOT IN ('', '!')");
    ob_start(); ?>
<h1>Tools</h1>
<section class="card"><h2>Store product photos on your server</h2>
  <p><?= number_format($local) ?> photos are saved on your server Â· <strong><?= number_format($remote) ?></strong> not saved yet.</p>
  <p class="muted small">Every photo already shows under your own address (kiratora.com/img/â€¦). The first time a photo is viewed, by a customer or by Google, your server saves its own copy, so this happens by itself. Press Start to save them all now instead: leave this page open while it runs, 25 photos at a time. You can pause and resume.</p>
  <div class="progress" hidden data-progress><div class="bar"><span data-bar></span></div><p class="small" data-progress-text></p></div>
