function admin_review_edit(): void {
    $id = (int)($_GET['id'] ?? 0);
    $r = $id ? one('SELECT * FROM reviews WHERE id = ?', [$id]) : null;
    if ($id && !$r) redirect('/admin/reviews');
    $r = $r ?: ['name' => '', 'location' => '', 'rating' => 5, 'title' => '', 'body' => '', 'product_id' => null, 'photo' => '', 'source' => '', 'review_date' => date('Y-m-d'), 'published' => 1, 'featured' => 1];
    $err = '';
    if (is_post()) {
        $d = $_POST;
        $pid = null;
        if (trim((string)($d['product'] ?? '')) !== '') {
            $ref = trim((string)$d['product']);
            if (preg_match('#/products/([a-z0-9-]+)#', $ref, $m)) $ref = $m[1];
            $pid = (int)(val('SELECT id FROM products WHERE handle = ?', [slugify($ref)]) ?? 0) ?: null;
            if (!$pid) $err = 'No product found for "' . $ref . '". Paste the product page address, or leave it empty for a shop review.';
        }
        if (trim((string)$d['name']) === '' || trim((string)$d['body']) === '') $err = 'Add the customer name and what they wrote.';
        if (!$err) {
            $photo = review_photo_upload();
            if (!empty($d['remove_photo']) && $r['photo']) { @unlink(ROOT . '/' . $r['photo']); $r['photo'] = ''; }
            $vals = ['name' => mb_substr(trim((string)$d['name']), 0, 80), 'location' => mb_substr(trim((string)$d['location']), 0, 80), 'rating' => max(1, min(5, (int)$d['rating'])),
                     'title' => mb_substr(trim((string)$d['title']), 0, 120), 'body' => mb_substr(trim((string)$d['body']), 0, 3000), 'product_id' => $pid,
                     'photo' => $photo ?? $r['photo'], 'source' => mb_substr(trim((string)$d['source']), 0, 60),
                     'review_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$d['review_date']) ? $d['review_date'] : date('Y-m-d'),
                     'published' => isset($d['published']) ? 1 : 0, 'featured' => isset($d['featured']) ? 1 : 0];
            if ($id) q('UPDATE reviews SET ' . implode(', ', array_map(fn($k) => "$k = ?", array_keys($vals))) . ' WHERE id = ?', [...array_values($vals), $id]);
            else q('INSERT INTO reviews(' . implode(',', array_keys($vals)) . ') VALUES(' . implode(',', array_fill(0, count($vals), '?')) . ')', array_values($vals));
            flash('Review saved.');
            redirect('/admin/reviews');
        }
        $r = array_merge($r, $d);
    }
    $prod = $r['product_id'] ? one('SELECT handle, title FROM products WHERE id = ?', [$r['product_id']]) : null;
    ob_start(); ?>
<p><a href="/admin/reviews">â† All reviews</a></p>
