function admin_main(string $path): void {
    start_session();
    $apath = '/' . trim(substr($path, strlen('/admin')), '/');

    /* ------------------------------------------------------------------ auth */
    if (setting('admin_password_hash') === '') {
        $err = '';
        if (is_post()) {
            csrf_check();
            $pw = (string)($_POST['password'] ?? '');
            if (mb_strlen($pw) < 10) $err = 'Use at least 10 characters.';
            elseif ($pw !== ($_POST['password2'] ?? '')) $err = 'The two passwords do not match.';
            else { set_setting('admin_password_hash', password_hash($pw, PASSWORD_DEFAULT)); session_regenerate_id(true); $_SESSION['admin'] = 1; $_SESSION['admin_ip'] = $_SERVER['REMOTE_ADDR'] ?? ''; redirect('/admin'); }
        }
        echo admin_shell('Create your admin password', '<form method="post" class="card narrow">' . csrf_field() . '<h1>Welcome to your Kiratora admin</h1><p class="muted">Create the password you will use to sign in. Keep it somewhere safe.</p>'
            . ($err ? '<p class="alert">' . h($err) . '</p>' : '') . '<label>Password<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><label>Repeat password<input type="password" name="password2" required autocomplete="new-password"></label><button class="btn primary">Create password</button></form>', '', false);
        exit;
    }
    if ($apath === '/logout') { $_SESSION = []; session_destroy(); redirect('/admin'); }
    if (!admin_ok()) {
        $err = '';
        $ip = $_SERVER['REMOTE_ADDR'] ?? '';
        $fails = json_decode(setting('login_fails'), true) ?: [];
        foreach ($fails as $k => $f) if ($f[1] < time() - 900) unset($fails[$k]);   // forget failures older than 15 minutes
        $locked = ($fails[$ip][0] ?? 0) >= 8;
        if (is_post()) {
            csrf_check();
            if ($locked) $err = 'Too many wrong attempts. Wait 15 minutes and try again.';
            else {
                $userOk = hash_equals(mb_strtolower(setting('admin_user')), mb_strtolower(trim((string)($_POST['user'] ?? ''))));
                if (password_verify((string)($_POST['password'] ?? ''), setting('admin_password_hash')) && $userOk) {
                    unset($fails[$ip]); set_setting('login_fails', json_encode($fails));
                    session_regenerate_id(true); $_SESSION['admin'] = 1; $_SESSION['admin_ip'] = $ip;
                    redirect('/admin' . ($apath !== '/' ? $apath : ''));
                }
                $fails[$ip] = [($fails[$ip][0] ?? 0) + 1, time()];
                set_setting('login_fails', json_encode($fails));
                usleep(700000);
                $err = 'That username or password is not right.';
            }
        }
        echo admin_shell('Sign in', '<form method="post" class="card narrow">' . csrf_field() . '<h1>Sign in</h1>' . ($err ? '<p class="alert">' . h($err) . '</p>' : '')
            . '<label>Username<input name="user" required autofocus autocomplete="username" value="' . h((string)($_POST['user'] ?? '')) . '"></label>'
            . '<label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary">Sign in</button></form>', '', false);
        exit;
    }
    if (is_post()) csrf_check();

    /* ------------------------------------------------------------------ routes */
    switch (true) {
        case $apath === '/': admin_dashboard(); break;
        case $apath === '/products': admin_products(); break;
        case $apath === '/products/edit': admin_product_edit(); break;
        case $apath === '/products/bulk': admin_products_bulk(); break;
        case $apath === '/import': admin_import(); break;
        case $apath === '/export': admin_export(); break;
        case $apath === '/orders': admin_orders(); break;
        case $apath === '/orders/view': admin_order_view(); break;
        case $apath === '/reviews': admin_reviews(); break;
        case $apath === '/reviews/edit': admin_review_edit(); break;
        case $apath === '/pages': admin_pages(); break;
        case $apath === '/pages/edit': admin_page_edit(); break;
        case $apath === '/collections/edit': admin_collection_edit(); break;
        case $apath === '/seo': admin_seo(); break;
        case $apath === '/redirects': admin_redirects(); break;
        case $apath === '/settings': admin_settings(); break;
        case $apath === '/tools': admin_tools(); break;
        case $apath === '/tools/images': admin_images_batch(); break;
        case $apath === '/tools/backup': admin_backup(); break;
        case $apath === '/upload': admin_upload(); break;
        default: http_response_code(404); echo admin_shell('Not found', '<div class="card"><h1>Not found</h1></div>', '');
    }


}

