        <tr><td class="mono"><?= h($r['card_number']) ?></td><td><a href="/products/<?= h($r['handle']) ?>"><?= h($nm) ?></a><?php if ($fin): ?><span class="muted small"><?= h($fin) ?></span><?php endif ?><?php if ($multiLang): ?> <span class="lang-tag"><?= h(['Japanese' => 'JP', 'English' => 'EN', 'Chinese' => 'CN'][$r['language']] ?? $r['language']) ?></span><?php endif ?></td><td class="small"><?= h($r['rarity']) ?></td><td class="mono num"><?= $r['price_usd'] !== null ? money((float)$r['price_usd']) : 'â€”' ?></td><td class="small <?= $r['in_stock'] ? 'ok' : 'muted' ?>"><?= $r['in_stock'] ? 'In stock' : 'Sold out' ?></td></tr>
      <?php endforeach ?></tbody>
