      <div class="quick-results" data-quick-results></div>
    </section>

    <section class="panel-box">
      <h2 class="h3">2 Â· Paste a list</h2>
      <p class="small muted">One product per line: <span class="mono">SKU or name, quantity</span>. Example:</p>
      <pre class="mono small example">Storm Emeralda Booster Box, 24
SV2a - 201/165, 2
6 x Abyss Eye Elite Trainer Box</pre>
      <form data-quick-paste>
        <label class="sr" for="ql">Your list</label>
        <textarea id="ql" class="input" name="lines" rows="8" placeholder="Paste your list here"></textarea>
        <button class="btn btn-primary" type="submit">Match products</button>
      </form>
      <div class="quick-matches" data-quick-matches hidden></div>
    </section>
  </div>
  <p class="center"><a class="btn btn-lg" href="/cart">Review your order â†’</a></p>
</div>
<?php }

function view_sets(array $__vars): void { extract($__vars, EXTR_SKIP); ?><?php
$groups = [];
foreach ($sets as $s) {
    $g = $s['game'] === 'PokÃ©mon' ? ($s['series'] ?: 'Japanese & special sets') : $s['game'];
    $groups[$g][] = $s;
}
uksort($groups, function ($a, $b) {
    $o = ['Mega Evolution' => 1, 'Scarlet & Violet' => 2, 'Japanese & special sets' => 3, 'Sword & Shield' => 4];
    return ($o[$a] ?? 10) <=> ($o[$b] ?? 10) ?: strcmp($a, $b);
});
?>
<div class="wrap">
  <nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>Sets</span></nav>
  <h1 class="h1"><?= h($h1) ?></h1>
  <?php if ($intro): ?><div class="intro prose"><?= $intro ?></div><?php else: ?><p class="lead muted">Every Japanese and English PokÃ©mon set in the shop, with the newest series first and other games below. Each set page prices every card and lists its sealed boxes.</p><?php endif ?>
  <label class="sr" for="setfilter">Find a set</label>
  <input id="setfilter" class="input setfilter" type="search" placeholder="Find a set, e.g. Prismatic" data-setfilter>
  <?php foreach ($groups as $g => $list): ?>
  <section class="section-sm" data-setgroup>
    <h2 class="eyebrow gold"><?= h($g) ?></h2>
    <div class="setlist">
      <?php foreach ($list as $s): ?><a href="<?= h($s['path']) ?>" data-name="<?= h(mb_strtolower($s['title'])) ?>"><span class="flex1"><?= h($s['title']) ?></span><span class="mono small muted"><?= number_format((int)$s['instock']) ?> in stock Â· <?= number_format((int)$s['n']) ?> â†’</span></a><?php endforeach ?>
    </div>
  </section>
  <?php endforeach ?>
</div>
<?php }

