/* ================================================================ Kiratora white & gold (final layer) */
:root{
  --surface:#FBFAF7;--raised:#FFFFFF;--sunken:#F5F2EA;--line:#E7E0D0;--line-strong:#CFC4AC;
  --ink:#1B1813;--muted:#6B6355;
  --shu:#B8912F;--shu-soft:#F6EFDC;--on-shu:#1B1813;
  --ai:#8C6A1C;--ai-soft:#F7F0DE;--kin:#9A7724;--kin-soft:#F7F0DE;
  --gold:#C9A13D;--gold-light:#8C6A1C;--gold-deep:#7A5C17;
  --holo:linear-gradient(135deg,#F3DE9A 0%,#DDB955 40%,#C9A13D 72%,#B08A2E 100%);
  --gold-grad:var(--holo);
  --focus:0 0 0 2px #FFFFFF,0 0 0 4px #B8912F;
  --hp-line:#EAE3D3;--hp-cell:#FBF9F4;--hp-cell-line:#ECE5D5;
