.tag-preorder,.tag-limited{background:#F6EFDC;color:#6E5312}
.feature,.feature.has-img{background:#FBF8F0;border-color:#ECE5D5}
.panel-foot{background:#F7F3EA;border-top:1px solid #ECE5D5}

/* the home page trust strip links to the promise behind each item, without changing its look */
.trust-list a{display:contents;color:inherit;text-decoration:none}
.trust-list a:hover strong,.trust-list a:focus-visible strong{text-decoration:underline}

/* legal links on the footer's bottom line */
.ftr-legal-links{display:flex;flex-wrap:wrap;gap:4px 16px}.ftr-legal-links a{color:inherit}

