/* Kiratora black & gold 3D.
   Three scenes drawn into page boxes from one canvas behind the page, plus faint gold dust in the background:
   1. hero:  the real Elite Trainer Box (built from its photo) on a glossy pedestal; its gold foil reflects a moving light;
             chase cards in gold frames circle it. Drag to turn, tap to open.
   2. vault: a cover-flow of chase cards with floor reflections and a spotlight. Swipe, use the arrows or the keyboard.
   3. star:  the Kiratora star in solid gold. Tap to spin.
   All words, links and prices stay in the HTML. The 3D starts after the page has loaded and is skipped on software graphics,
   reduced motion, data saver and very low-memory devices, which keep the still pictures. */
(() => {
  const dataEl = document.getElementById('luxe-data');
  const mq = q => window.matchMedia(q).matches;
  const FINE = mq('(hover: hover) and (pointer: fine)');
  const REDUCED = mq('(prefers-reduced-motion: reduce)');

  /* ---------- tilt and gold sheen on product cards and tiles (every page, mouse only) */
  if (FINE && !REDUCED) {
    const SEL = '.card, .tile, .hp .setlist a, .hp .names a';
    let cur = null;
    const off = el => { el.classList.remove('lux-on'); el.style.transform = ''; };
    document.addEventListener('pointermove', e => {
      const el = e.target.closest && e.target.closest(SEL);
      if (cur && cur !== el) off(cur);
      cur = el; if (!el) return;
      const r = el.getBoundingClientRect(), x = (e.clientX - r.left) / r.width, y = (e.clientY - r.top) / r.height;
      const m = el.classList.contains('card') ? 7 : 5;
      el.classList.add('lux-on');
      el.style.transform = `perspective(900px) rotateX(${((.5 - y) * m).toFixed(2)}deg) rotateY(${((x - .5) * m).toFixed(2)}deg) translateY(-2px)`;
      el.style.setProperty('--mx', (x * 100).toFixed(1) + '%'); el.style.setProperty('--my', (y * 100).toFixed(1) + '%');
    }, {passive: true});
