        onDrag: dx => { vel = dx * .25; },
        onTap: () => { vel += 9; },
        update: (t, dt, w) => {
          cam.position.set(s.px * 1.2, -s.py * .8 + .2, w < 560 ? 11.5 : 10); cam.lookAt(0, -.3, 0);
          vel += (.35 - vel) * Math.min(1, dt * 1.2); rot += vel * dt;
